#nullable enable // autogenerated

using MVZ2Logic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Games;
using MVZ2Logic.Models;
using MVZ2Logic.UI;
using PVZEngine;
using UnityEngine;

namespace MVZ2.GameContent.Models
{
    public class ArtifactPickupModel : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            base.UpdateFrame(deltaTime);
            var artifactID = Model.GetProperty<NamespaceID>("ContentID");
            if (lastID != artifactID)
            {
                lastID = artifactID;
                var artifactDef = Global.Game.GetArtifactDefinition(artifactID);
                if (artifactDef == null)
                    return;
                var sprRef = artifactDef.GetSpriteReference();
                artifactSprite.SetSprite(Global.Resources?.GetSprite(sprRef));
            }
        }
        [SerializeField]
        private SpriteRendererResolver artifactSprite = null!;
        private NamespaceID? lastID;
    }
}
